from google.cloud import logging_v2

def get_client(project_id, log_name):
    return logging_v2.Client(project=project_id), logging_v2.Client(project=project_id).logger(log_name)

from google.cloud.logging_v2.resource import Resource

def create_resource(type, labels):
    return Resource(type=type, labels=labels)
